<template><div class="alert" :class="`alert--${severity}`" role="alert"><div><strong v-if="title">{{ title }}</strong><slot /></div><Button v-if="retry" variant="ghost" @click="$emit('retry')">重试</Button></div></template>
<script setup lang="ts">import Button from './Button.vue'; withDefaults(defineProps<{ severity?: 'info' | 'success' | 'warning' | 'danger'; title?: string; retry?: boolean }>(), { severity: 'info', retry: false }); defineEmits<{ retry: [] }>();</script>
<style scoped>.alert { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); padding: var(--space-3); border: 1px solid currentColor; border-radius: var(--radius); }.alert--info { color: var(--info); background: var(--info-soft); }.alert--success { color: var(--ok); background: var(--ok-soft); }.alert--warning { color: var(--warn); background: var(--warn-soft); }.alert--danger { color: var(--danger); background: var(--danger-soft); }</style>
